 * The scanner for the small language described in the task prompt. It turns
 * source text into a flat list of tokens, or throws a `LexError` carrying the
 * line, column and reason of the first thing that does not scan.
 */

const KEYWORDS = new Set(['let', 'if', 'else', 'while', 'return', 'true', 'false', 'null'])

const TWO_CHAR_PUNCT = ['==', '!=', '<=', '>=', '&&', '||', '->', '=>']
const ONE_CHAR_PUNCT = new Set(['+', '-', '*', '/', '%', '=', '<', '>', '!', '(', ')', '{', '}', '[', ']', ',', ';', '.'])

export class LexError extends Error {
  constructor(line, column, reason) {
    super(`${line}:${column}: ${reason}`)
    this.line = line
    this.column = column
    this.reason = reason
  }
}

function isDecDigit(c) {
  return c >= '0' && c <= '9'
}

function isHexDigit(c) {
  return (c >= '0' && c <= '9') || (c >= 'a' && c <= 'f') || (c >= 'A' && c <= 'F')
}

function isBinDigit(c) {
  return c === '0' || c === '1'
}

function isOctDigit(c) {
  return c >= '0' && c <= '7'
}

function isLetter(c) {
  return (c >= 'a' && c <= 'z') || (c >= 'A' && c <= 'Z')
}

function isIdentStart(c) {
  return isLetter(c) || c === '_'
}

function isIdentPart(c) {
  return isLetter(c) || isDecDigit(c) || c === '_'
}

function isTrailingInvalid(c) {
  return c !== undefined && (isLetter(c) || isDecDigit(c) || c === '_')
}

/** Splits `text` into code points and, for each one, the line and column it sits at. */
function computePositions(chars) {
  const positions = new Array(chars.length + 1)
  let line = 1
  let col = 1
  for (let i = 0; i < chars.length; i++) {
    positions[i] = { line, column: col }
    const c = chars[i]
    if (c === '\n') {
      line++
      col = 1
    } else if (c === '\t') {
      col = Math.floor((col - 1) / 4) * 4 + 5
    } else {
      col++
    }
  }
  positions[chars.length] = { line, column: col }
  return positions
}

/** Scans `source` into an array of `{ line, column, kind, text }` tokens. */
export function lex(source) {
  const chars = Array.from(source)
  const positions = computePositions(chars)
  const n = chars.length
  const tokens = []
  let i = 0

  const posAt = (index) => positions[index]

  function errorAt(index, reason) {
    const p = posAt(index)
    throw new LexError(p.line, p.column, reason)
  }

  // Consumes the maximal run of `test`-satisfying digits starting at `chars[i]`
  // (which must already satisfy `test`), allowing a single `_` between two
  // digits of the run.
  function consumeDigitRun(test) {
    i++
    while (true) {
      if (i < n && test(chars[i])) {
        i++
        continue
      }
      if (i < n && chars[i] === '_' && i + 1 < n && test(chars[i + 1])) {
        i += 2
        continue
      }
      break
    }
  }

  function scanNumber() {
    const start = i
    const startPos = posAt(start)
    if (chars[i] === '0' && i + 1 < n && /[xXbBoO]/.test(chars[i + 1])) {
      const prefixChar = chars[i + 1]
      const test = prefixChar === 'x' || prefixChar === 'X' ? isHexDigit : prefixChar === 'b' || prefixChar === 'B' ? isBinDigit : isOctDigit
      const afterPrefix = i + 2
      if (afterPrefix >= n || !test(chars[afterPrefix])) {
        const text = chars.slice(start, afterPrefix).join('')
        throw new LexError(startPos.line, startPos.column, `invalid number ${text}`)
      }
      i = afterPrefix
      consumeDigitRun(test)
    } else {
      consumeDigitRun(isDecDigit)
      if (chars[i] === '.' && i + 1 < n && isDecDigit(chars[i + 1])) {
        i++
        consumeDigitRun(isDecDigit)
      }
      if (chars[i] === 'e' || chars[i] === 'E') {
        let p = i + 1
        if (chars[p] === '+' || chars[p] === '-') p++
        if (p < n && isDecDigit(chars[p])) {
          i = p
          consumeDigitRun(isDecDigit)
        }
      }
    }
    if (isTrailingInvalid(chars[i])) {
      const text = chars.slice(start, i + 1).join('')
      throw new LexError(startPos.line, startPos.column, `invalid number ${text}`)
    }
    const text = chars.slice(start, i).join('')
    tokens.push({ line: startPos.line, column: startPos.column, kind: 'number', text })
  }

  function scanIdent() {
    const start = i
    const startPos = posAt(start)
    i++
    while (i < n && isIdentPart(chars[i])) i++
    const text = chars.slice(start, i).join('')
    tokens.push({ line: startPos.line, column: startPos.column, kind: KEYWORDS.has(text) ? 'keyword' : 'ident', text })
  }

  function readEscapeHex(count) {
    // Reads exactly `count` hex digits starting at `i`; returns null if not available.
    for (let k = 0; k < count; k++) {
      if (i + k >= n || !isHexDigit(chars[i + k])) return null
    }
    const text = chars.slice(i, i + count).join('')
    i += count
    return text
  }

  function scanString() {
    const startPos = posAt(i)
    i++ // skip opening quote
    let value = ''
    while (true) {
      if (i >= n) throw new LexError(startPos.line, startPos.column, 'unterminated string')
      const c = chars[i]
      if (c === '"') {
        i++
        break
      }
      if (c === '\n') errorAt(i, 'newline in string')
      if (c === '\\') {
        const bpos = posAt(i)
        i++
        if (i >= n) throw new LexError(startPos.line, startPos.column, 'unterminated string')
        const e = chars[i]
        if (e === 'n') {
          value += '\n'
          i++
        } else if (e === 't') {
          value += '\t'
          i++
        } else if (e === 'r') {
          value += '\r'
          i++
        } else if (e === '\\') {
          value += '\\'
          i++
        } else if (e === '"') {
          value += '"'
          i++
        } else if (e === '0') {
          value += '\0'
          i++
        } else if (e === 'x') {
          i++
          const hex = readEscapeHex(2)
          if (hex === null) throw new LexError(bpos.line, bpos.column, 'invalid escape \\x')
          value += String.fromCharCode(parseInt(hex, 16))
        } else if (e === 'u') {
          i++
          if (chars[i] !== '{') throw new LexError(bpos.line, bpos.column, 'invalid escape \\u')
          i++
          let hex = ''
          while (i < n && isHexDigit(chars[i])) {
            hex += chars[i]
            i++
          }
          if (hex.length === 0 || chars[i] !== '}') throw new LexError(bpos.line, bpos.column, 'invalid escape \\u')
          i++
          const code = parseInt(hex, 16)
          if (code > 0x10ffff) throw new LexError(bpos.line, bpos.column, 'invalid escape \\u')
          value += String.fromCodePoint(code)
        } else {
          throw new LexError(bpos.line, bpos.column, `invalid escape \\${e}`)
        }
      } else {
        value += c
        i++
      }
    }
    tokens.push({ line: startPos.line, column: startPos.column, kind: 'string', text: JSON.stringify(value) })
  }

  function scanRawString() {
    const startPos = posAt(i) // position of the `r`
    i += 2 // skip `r"`
    let value = ''
    while (true) {
      if (i >= n) throw new LexError(startPos.line, startPos.column, 'unterminated string')
      const c = chars[i]
      if (c === '"') {
        i++
        break
      }
      value += c
      i++
    }
    tokens.push({ line: startPos.line, column: startPos.column, kind: 'rawstring', text: JSON.stringify(value) })
  }

  while (i < n) {
    const c = chars[i]
    if (c === ' ' || c === '\t' || c === '\r' || c === '\n') {
      i++
      continue
    }
    if (c === '/' && chars[i + 1] === '/') {
      i += 2
      while (i < n && chars[i] !== '\n') i++
      continue
    }
    if (c === '/' && chars[i + 1] === '*') {
      const startPos = posAt(i)
      let depth = 1
      i += 2
      while (depth > 0) {
        if (i >= n) throw new LexError(startPos.line, startPos.column, 'unterminated block comment')
        if (chars[i] === '*' && chars[i + 1] === '/') {
          depth--
          i += 2
        } else if (chars[i] === '/' && chars[i + 1] === '*') {
          depth++
          i += 2
        } else {
          i++
        }
      }
      continue
    }
    if (c === '"') {
      scanString()
      continue
    }
    if (c === 'r' && chars[i + 1] === '"') {
      scanRawString()
      continue
    }
    if (isIdentStart(c)) {
      scanIdent()
      continue
    }
    if (isDecDigit(c)) {
      scanNumber()
      continue
    }
    const two = c + (chars[i + 1] ?? '')
    if (TWO_CHAR_PUNCT.includes(two)) {
      tokens.push({ line: posAt(i).line, column: posAt(i).column, kind: 'punct', text: two })
      i += 2
      continue
    }
    if (ONE_CHAR_PUNCT.has(c)) {
      tokens.push({ line: posAt(i).line, column: posAt(i).column, kind: 'punct', text: c })
      i++
      continue
    }
    errorAt(i, `unexpected character ${c}`)
  }

  return tokens
}
"}

